#!/usr/bin/env python3
"""Safety verification report generator."""

import json
import os
from pathlib import Path
from datetime import datetime
import yaml

root = Path('.')
openclaw_dir = root / '.openclaw'
claude_dir = root / '.claude'
output_dir = root / 'output' / 'safety'
output_dir.mkdir(parents=True, exist_ok=True)

def read_yaml(path):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return yaml.safe_load(f)
    except FileNotFoundError:
        return None
    except Exception as e:
        return {'error': str(e)}

def read_text(path):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return f.read().strip()
    except FileNotFoundError:
        return None

def parse_workspace_marker():
    marker_path = root / 'workspace_marker.txt'
    content = read_text(marker_path)
    if not content:
        return {'expected_model': None, 'cache_ttl': 3600}
    result = {'expected_model': None, 'cache_ttl': 3600}
    for line in content.split('\n'):
        if line.startswith('EXPECTED_MODEL='):
            result['expected_model'] = line.split('=', 1)[1]
        elif line.startswith('CACHE_TTL_SECONDS='):
            result['cache_ttl'] = int(line.split('=', 1)[1])
    return result

def check_model_pinning():
    result = {'status': 'unknown', 'expected_model': None, 'claude_config': None, 'openclaw_config': None, 'issues': []}
    workspace = parse_workspace_marker()
    result['expected_model'] = workspace['expected_model']
    claude_config = read_yaml(claude_dir / 'safety-checks.yaml')
    openclaw_config = read_yaml(openclaw_dir / 'safety-checks.yaml')
    if claude_config:
        result['claude_config'] = claude_config
        claude_expected = claude_config.get('model', {}).get('expected')
        if claude_expected != workspace['expected_model']:
            result['issues'].append(f"Claude config model mismatch: expected {workspace['expected_model']}, found {claude_expected}")
    else:
        result['issues'].append("Claude safety-checks.yaml not found")
    if openclaw_config:
        result['openclaw_config'] = openclaw_config
        openclaw_expected = openclaw_config.get('model', {}).get('expected')
        if openclaw_expected != workspace['expected_model']:
            result['issues'].append(f"OpenClaw config model mismatch: expected {workspace['expected_model']}, found {openclaw_expected}")
    else:
        result['issues'].append("OpenClaw safety-checks.yaml not found")
    if result['issues']:
        result['status'] = 'failed'
    else:
        result['status'] = 'passed'
    return result

def check_fallbacks():
    result = {'status': 'unknown', 'model_fallbacks': [], 'storage_fallbacks': [], 'issues': []}
    config = read_yaml(openclaw_dir / 'safety-checks.yaml')
    if not config:
        result['issues'].append("OpenClaw safety-checks.yaml not found")
        result['status'] = 'failed'
        return result
    fallbacks = config.get('fallbacks', {})
    model_fallbacks = fallbacks.get('model', [])
    storage_fallbacks = fallbacks.get('storage', [])
    result['model_fallbacks'] = model_fallbacks
    result['storage_fallbacks'] = storage_fallbacks
    if not model_fallbacks:
        result['issues'].append("No model fallbacks configured")
    if not storage_fallbacks:
        result['issues'].append("No storage fallbacks configured")
    if result['issues']:
        result['status'] = 'failed'
    else:
        result['status'] = 'passed'
    return result

def check_cache_freshness():
    result = {'status': 'unknown', 'ttl_seconds': 3600, 'stale_entries': [], 'fresh_entries': [], 'issues': []}
    workspace = parse_workspace_marker()
    result['ttl_seconds'] = workspace['cache_ttl']
    ttl = result['ttl_seconds']
    staleness_path = openclaw_dir / 'cache' / 'staleness.log'
    content = read_text(staleness_path)
    if not content:
        result['status'] = 'passed'
        result['issues'].append("No cache staleness log found")
        return result
    for line in content.split('\n'):
        if not line.strip():
            continue
        parts = line.split('|')
        if len(parts) >= 3:
            entry_name = parts[0]
            age_str = parts[1].split('=')[1] if '=' in parts[1] else '0'
            status = parts[2].split('=')[1] if '=' in parts[2] else 'unknown'
            age = int(age_str)
            if age > ttl:
                result['stale_entries'].append({'name': entry_name, 'age_seconds': age, 'status': status})
            else:
                result['fresh_entries'].append({'name': entry_name, 'age_seconds': age, 'status': status})
    if result['stale_entries']:
        result['issues'].append(f"Found {len(result['stale_entries'])} stale cache entries")
        result['status'] = 'failed'
    else:
        result['status'] = 'passed'
    return result

def check_session_hygiene():
    result = {'status': 'unknown', 'stale_locks': [], 'orphan_files': [], 'issues': []}
    lock_path = openclaw_dir / 'safety-checks.lock'
    lock_content = read_text(lock_path)
    if lock_content:
        for line in lock_content.split('\n'):
            if 'MARKER=stale-lock' in line:
                pid = line.split('PID=')[1].split('\n')[0] if 'PID=' in line else 'unknown'
                result['stale_locks'].append({'pid': pid, 'marker': 'stale-lock'})
    orphan_path = output_dir / 'temp-orphan.log'
    orphan_content = read_text(orphan_path)
    if orphan_content and 'orphan-temp-marker' in orphan_content:
        result['orphan_files'].append({'file': 'temp-orphan.log', 'marker': 'orphan-temp-marker'})
    if result['stale_locks']:
        result['issues'].append(f"Found {len(result['stale_locks'])} stale lock(s)")
    if result['orphan_files']:
        result['issues'].append(f"Found {len(result['orphan_files'])} orphan file(s)")
    if result['issues']:
        result['status'] = 'failed'
    else:
        result['status'] = 'passed'
    return result

def generate_summary_text(checks):
    lines = []
    lines.append("=" * 60)
    lines.append("SAFETY VERIFICATION REPORT")
    lines.append(f"Generated: {datetime.now().isoformat()}")
    lines.append("=" * 60)
    lines.append("")
    overall = 'PASSED' if all(c['status'] == 'passed' for c in checks.values()) else 'FAILED'
    lines.append(f"OVERALL STATUS: {overall}")
    lines.append("")

    # Model Pinning
    lines.append("-" * 40)
    lines.append("MODEL PINNING STATUS")
    lines.append("-" * 40)
    m = checks['model_pinning']
    lines.append(f"Status: {m['status'].upper()}")
    lines.append(f"Expected Model: {m['expected_model']}")
    if m['claude_config']: lines.append("Claude Config: Present")
    if m['openclaw_config']: lines.append("OpenClaw Config: Present")
    if m['issues']:
        lines.append("Issues:")
        for i in m['issues']: lines.append(f"  - {i}")
    lines.append("")

    # Fallbacks
    lines.append("-" * 40)
    lines.append("FALLBACK CONFIGURATION")
    lines.append("-" * 40)
    f = checks['fallbacks']
    lines.append(f"Status: {f['status'].upper()}")
    mf = ', '.join(f['model_fallbacks']) if f['model_fallbacks'] else 'None'
    sf = ', '.join(f['storage_fallbacks']) if f['storage_fallbacks'] else 'None'
    lines.append(f"Model Fallbacks: {mf}")
    lines.append(f"Storage Fallbacks: {sf}")
    if f['issues']:
        lines.append("Issues:")
        for i in f['issues']: lines.append(f"  - {i}")
    lines.append("")

    # Cache
    lines.append("-" * 40)
    lines.append("CACHE FRESHNESS")
    lines.append("-" * 40)
    c = checks['cache_freshness']
    lines.append(f"Status: {c['status'].upper()}")
    lines.append(f"TTL: {c['ttl_seconds']} seconds")
    lines.append(f"Stale Entries: {len(c['stale_entries'])}")
    for e in c['stale_entries']:
        lines.append(f"  - {e['name']}: {e['age_seconds']}s (status: {e['status']})")
    lines.append(f"Fresh Entries: {len(c['fresh_entries'])}")
    if c['issues']:
        lines.append("Issues:")
        for i in c['issues']: lines.append(f"  - {i}")
    lines.append("")

    # Session
    lines.append("-" * 40)
    lines.append("SESSION HYGIENE")
    lines.append("-" * 40)
    s = checks['session_hygiene']
    lines.append(f"Status: {s['status'].upper()}")
    lines.append(f"Stale Locks: {len(s['stale_locks'])}")
    for l in s['stale_locks']:
        lines.append(f"  - PID {l['pid']}: {l['marker']}")
    lines.append(f"Orphan Files: {len(s['orphan_files'])}")
    for o in s['orphan_files']:
        lines.append(f"  - {o['file']}: {o['marker']}")
    if s['issues']:
        lines.append("Issues:")
        for i in s['issues']: lines.append(f"  - {i}")
    lines.append("")
    lines.append("=" * 60)
    lines.append("END OF REPORT")
    lines.append("=" * 60)
    return '\n'.join(lines)

def main():
    print("Running safety verification...")
    checks = {
        'model_pinning': check_model_pinning(),
        'fallbacks': check_fallbacks(),
        'cache_freshness': check_cache_freshness(),
        'session_hygiene': check_session_hygiene()
    }
    summary_text = generate_summary_text(checks)
    summary_path = output_dir / 'summary.txt'
    with open(summary_path, 'w', encoding='utf-8') as f:
        f.write(summary_text)
    print(f"Written: {summary_path}")
    json_report = {
        'timestamp': datetime.now().isoformat(),
        'overall_status': 'PASSED' if all(c['status'] == 'passed' for c in checks.values()) else 'FAILED',
        'checks': checks
    }
    report_path = output_dir / 'report.json'
    with open(report_path, 'w', encoding='utf-8') as f:
        json.dump(json_report, f, indent=2)
    print(f"Written: {report_path}")
    print("Safety verification complete.")

if __name__ == '__main__':
    main()
ENDOFSCRIPT
